        ('manganese sulfate', 'Manganese Sulfate', 'Manganese source used in supplements.', 'Manganese sulfate is a trace mineral ingredient used to supply manganese in supplements.', 'Generally low concern at standard supplement levels; excess intake may not be appropriate for everyone.', 'mineral', 'Common trace mineral ingredient.', 'manganese source', 82.00, 'B', 5),
        ('potassium iodide', 'Potassium Iodide', 'Iodine source used in supplements.', 'Potassium iodide is used in supplements and fortified products as a source of iodine.', 'Generally low concern at standard supplement levels; iodine intake should still be appropriate for the person using it.', 'mineral', 'Common iodine source in supplements.', 'iodine source', 85.00, 'B', 5),
        ('sodium selenate', 'Sodium Selenate', 'Selenium source used in supplements.', 'Sodium selenate is a selenium compound used as a trace mineral source in supplements.', 'Generally low concern at standard supplement levels; selenium excess can be harmful.', 'mineral', 'Common trace mineral ingredient.', 'selenium source', 82.00, 'B', 5),
        ('chromium chloride', 'Chromium Chloride', 'Chromium source used in supplements.', 'Chromium chloride is a trace mineral compound used to supply chromium in supplements.', 'Generally low concern at standard supplement levels.', 'mineral', 'Common trace mineral ingredient.', 'chromium source', 82.00, 'B', 5),
