        ('retinyl acetate', 'Retinyl Acetate', 'Vitamin A ingredient used in supplements.', 'Retinyl acetate is a form of vitamin A used in supplements and fortified products.', 'Useful nutrient ingredient, but vitamin A dosing matters and excess intake can be a concern.', 'vitamin', 'Common supplemental vitamin A form.', 'vitamin a source', 80.00, 'B', 5),
        ('retinyl palmitate', 'Retinyl Palmitate', 'Vitamin A ingredient used in supplements.', 'Retinyl palmitate is a form of vitamin A used in supplements and fortified products.', 'Useful nutrient ingredient, but vitamin A dosing matters and excess intake can be a concern.', 'vitamin', 'Common supplemental vitamin A form.', 'vitamin a source', 80.00, 'B', 5),
