upserted AS (
    INSERT INTO ingredients (
        canonical_key,
        display_name,
        summary,
        description,
        concerns,
        category,
        regulation_notes,
        func_use,
        safety_score,
        rating_letter,
        references_count,
        is_active
    )
    SELECT canonical_key,
           display_name,
           summary,
           description,
           concerns,
           category,
           regulation_notes,
           func_use,
           safety_score,
           rating_letter,
           references_count,
           TRUE
    FROM seed
    ON CONFLICT (canonical_key) DO UPDATE
    SET display_name = COALESCE(NULLIF(ingredients.display_name, ''), EXCLUDED.display_name),
        summary = COALESCE(NULLIF(ingredients.summary, ''), EXCLUDED.summary),
        description = COALESCE(NULLIF(ingredients.description, ''), EXCLUDED.description),
        concerns = COALESCE(NULLIF(ingredients.concerns, ''), EXCLUDED.concerns),
        category = COALESCE(NULLIF(ingredients.category, ''), EXCLUDED.category),
        regulation_notes = COALESCE(NULLIF(ingredients.regulation_notes, ''), EXCLUDED.regulation_notes),
        func_use = COALESCE(NULLIF(ingredients.func_use, ''), EXCLUDED.func_use),
        safety_score = COALESCE(ingredients.safety_score, EXCLUDED.safety_score),
        rating_letter = COALESCE(NULLIF(ingredients.rating_letter, ''), EXCLUDED.rating_letter),
        references_count = COALESCE(ingredients.references_count, EXCLUDED.references_count)
    RETURNING canonical_key
)
SELECT count(*) FROM upserted;

INSERT INTO ingredient_alias (ingredient_id, alias)
